// supabase/functions/rate-check-partner/w9Form.ts
// The blank IRS Form W-9, page 1 only (the fillable form; the instructions aren't
// kept), as base64 so the function can fill it with pdf-lib. To swap revisions,
// regenerate this file from the new PDF: trim to page 1 with pypdf (append page 0
// to a PdfWriter keeps the fields), base64 it, update W9_REVISION. The field names
// (f1_01 … f1_15, c1_1[0..6], c1_2) are the IRS's and have been stable across
// revisions; the June 2026 revision adds date fields f1_16-18, which the function
// fills when present and otherwise draws the date as text.
//
// CURRENT FILE: the official form from irs.gov/pub/irs-pdf/fw9.pdf.
export const W9_REVISION = 'Rev. March 2024'
export const W9_PDF_BASE64 = ''
